{
  "objective": "Using validation-only evidence, produce bounded research and risk directives for the frozen Phase 12 protocol. Never access test metrics.",
  "mode": "dry_run",
  "rationale": "The dataset manifest (formal_v3) has been inspected and is quality-valid, covering 4 markets (CN, HK, JP, US), 80 symbols, and 73,193 rows. The proposed steps are restricted to validation-only actions—dataset inspection, validation, market/symbol enumeration, split creation, experiment config validation, and compute estimation—ensuring no training, tuning, evaluation, or comparison that could access test metrics. This bounds risk and provides a safe audit trail for Phase 12.",
  "confidence": 0.85,
  "estimated_compute_units": 0.5,
  "safe_to_execute": false,
  "test_metrics_accessed": false,
  "validation_only": true,
  "steps": [
    {
      "id": "step-1",
      "action": "inspect_dataset",
      "arguments": {
        "manifest_path": "data/processed/formal_v3/dataset_manifest.json"
      },
      "depends_on": [],
      "expected_artifacts": ["dataset_manifest_summary"]
    },
    {
      "id": "step-2",
      "action": "validate_dataset",
      "arguments": {
        "manifest_path": "data/processed/formal_v3/dataset_manifest.json"
      },
      "depends_on": ["step-1"],
      "expected_artifacts": ["dataset_quality_report"]
    },
    {
      "id": "step-3",
      "action": "list_markets",
      "arguments": {
        "manifest_path": "data/processed/formal_v3/dataset_manifest.json"
      },
      "depends_on": ["step-2"],
      "expected_artifacts": ["market_list"]
    },
    {
      "id": "step-4",
      "action": "list_symbols",
      "arguments": {
        "manifest_path": "data/processed/formal_v3/dataset_manifest.json",
        "markets": ["CN", "HK", "JP", "US"]
      },
      "depends_on": ["step-3"],
      "expected_artifacts": ["symbol_list"]
    },
    {
      "id": "step-5",
      "action": "create_split",
      "arguments": {
        "manifest_path": "data/processed/formal_v3/dataset_manifest.json",
        "split_type": "time_series",
        "train_ratio": 0.8,
        "validation_ratio": 0.2,
        "test_ratio": 0.0
      },
      "depends_on": ["step-4"],
      "expected_artifacts": ["split_indices"]
    },
    {
      "id": "step-6",
      "action": "validate_experiment_config",
      "arguments": {
        "manifest_path": "data/processed/formal_v3/dataset_manifest.json",
        "experiment_name": "phase12_frozen"
      },
      "depends_on": ["step-5"],
      "expected_artifacts": ["config_validation_report"]
    },
    {
      "id": "step-7",
      "action": "estimate_compute_budget",
      "arguments": {
        "manifest_path": "data/processed/formal_v3/dataset_manifest.json",
        "num_symbols": 80,
        "num_markets": 4,
        "experiment_config": "phase12_frozen"
      },
      "depends_on": ["step-6"],
      "expected_artifacts": ["compute_estimate"]
    }
  ]
}
